### Explanation
This code is vulnerable to OS Command Injection (CWE-78) because it constructs a shell command string using user input (`username`) directly in a template literal. An attacker could inject arbitrary shell commands by providing a malicious `username` such as `username; rm -rf /`, which would execute unintended commands. This could lead to complete system compromise.

### Fixed code
```javascript
const { execFile } = require('child_process');

function deleteUserAccount(username) {
  // Validate username against a strict allow-list regex (e.g., alphanumeric and underscores only)
  const usernameRegex = /^[a-zA-Z0-9_]+$/;
  if (!usernameRegex.test(username)) {
    throw new Error('Invalid username format');
  }

  // Use execFile with an argument array to avoid shell injection
  execFile('userdel', ['-r', username], (error, stdout, stderr) => {
    if (error) {
      console.error(`Failed to delete user: ${error.message}`);
      return;
    }
    console.log(`Account deleted: ${username}`);
  });
}
```

